const geo = msg.payload.data.geometry;
const lng = geo.coordinates[0];
const lat = geo.coordinates[1];
const zoom = 15;

const latRad = lat * Math.PI / 180;
const n = Math.pow(2, zoom);
const tileX = Math.floor((lng + 180) / 360 * n);
const tileY = Math.floor((1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2 * n);

const exactX = (lng + 180) / 360 * n;
const exactY = (1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2 * n;

msg.marker = {
    x: Math.round((exactX - tileX + 1) * 256),
    y: Math.round((exactY - tileY + 1) * 256)
};

msg.tiles = [];
for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
        msg.tiles.push({
            url: "https://tile.openstreetmap.org/" + zoom + "/" + (tileX + dx) + "/" + (tileY + dy) + ".png",
            x: (dx + 1) * 256,
            y: (dy + 1) * 256
        });
    }
}

return msg;

const composites = msg.tiles.map(function (tile) {
    return { input: tile.buffer, left: tile.x, top: tile.y };
});

const markerSize = 16;
const markerSvg = Buffer.from(
    '<svg width="' + markerSize + '" height="' + markerSize + '">' +
    '<circle cx="8" cy="8" r="7" fill="red" stroke="white" stroke-width="2"/>' +
    '</svg>'
);

composites.push({
    input: markerSvg,
    left: msg.marker.x - markerSize / 2,
    top: msg.marker.y - markerSize / 2
});

sharp({
    create: { width: 768, height: 768, channels: 4, background: { r: 200, g: 200, b: 200, alpha: 1 } }
})
    .composite(composites)
    .jpeg({ quality: 95 })
    .toBuffer()
    .then(function (jpegBuffer) {
        msg.mapImage = {
            name: "location_" + Date.now() + ".jpg",
            type: "image/jpeg",
            buffer: jpegBuffer
        };
        delete msg.tiles;
        delete msg.marker;
        node.send(msg);
    })
    .catch(function (err) {
        node.error("Map composite failed: " + err.message, msg);
    });

return null;

function fetchTile(url) {
    return new Promise(function (resolve, reject) {
        https.get(url, { headers: { "User-Agent": "Parat-Bridge/1.0" } }, function (res) {
            if (res.statusCode !== 200) {
                reject(new Error("Tile " + url + " returned " + res.statusCode));
                return;
            }
            const chunks = [];
            res.on("data", function (chunk) { chunks.push(chunk); });
            res.on("end", function () { resolve(Buffer.concat(chunks)); });
            res.on("error", reject);
        }).on("error", reject);
    });
}

const promises = msg.tiles.map(function (t) { return fetchTile(t.url); });

Promise.all(promises).then(function (buffers) {
    buffers.forEach(function (buf, i) {
        msg.tiles[i].buffer = buf;
    });
    node.send(msg);
}).catch(function (err) {
    node.error("Tile fetch failed: " + err.message, msg);
});

return null;
